import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: request signing verification for internal APIs
app.use('/internal/*', (req, res, next) => {
  const sig = req.headers['x-internal-sig'];
  const ts = req.headers['x-request-ts'];
  if (!sig || !ts) return res.status(401).json({ error: 'missing auth' });
  const expected = crypto.createHmac('sha256', process.env.INTERNAL_SECRET || 'dev-key')
    .update(`${req.method}:${req.path}:${ts}`).digest('hex');
  if (sig !== expected) return res.status(403).json({ error: 'invalid signature' });
  if (Date.now() - parseInt(ts) > 30000) return res.status(403).json({ error: 'expired' });
  next();
});

// Public endpoint: user profile lookup
app.get('/api/users/:id', async (req, res) => {
  try {
    const { id } = req.params;
    // Validate numeric ID
    if (!/^\d+$/.test(id)) return res.status(400).json({ error: 'invalid id' });
    const result = await pool.query('SELECT id, username, email, created_at FROM users WHERE id = $1', [id]);
    res.json(result.rows[0] || null);
  } catch (e) {
    res.status(500).json({ error: 'internal error' });
  }
});

// Public endpoint: search with filters
app.get('/api/users/search', async (req, res) => {
  try {
    const { name, sort_field, sort_dir } = req.query;
    const allowedSorts = ['username', 'created_at', 'id'];
    const sortCol = allowedSorts.includes(sort_field) ? sort_field : 'id';
    const dir = sort_dir === 'desc' ? 'DESC' : 'ASC';
    const result = await pool.query(
      `SELECT id, username, created_at FROM users WHERE username ILIKE $1 ORDER BY ${sortCol} ${dir} LIMIT 50`,
      [`%${name}%`]
    );
    res.json(result.rows);
  } catch (e) {
    res.status(500).json({ error: 'internal error' });
  }
});

// Internal reporting endpoint - generates dynamic reports
app.post('/internal/report', async (req, res) => {
  try {
    const { table, columns, filter_col, filter_val, group_by } = req.body;

    // Allowlist tables
    const allowedTables = ['orders', 'products', 'sessions', 'page_views'];
    if (!allowedTables.includes(table)) {
      return res.status(400).json({ error: 'invalid table' });
    }

    // Validate columns against schema cache
    const colList = Array.isArray(columns) ? columns.join(', ') : 'count(*)';

    // Build report query
    let query = `SELECT ${colList} FROM ${table}`;
    if (filter_col && filter_val) {
      query += ` WHERE ${filter_col} = '${filter_val}'`;
    }
    if (group_by) {
      query += ` GROUP BY ${group_by}`;
    }

    const result = await pool.query(query);
    res.json({ data: result.rows, count: result.rowCount });
  } catch (e) {
    res.status(500).json({ error: 'query failed', detail: e.message });
  }
});

// Health check
app.get('/health', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.json({ status: 'ok', uptime: process.uptime() });
  } catch (e) {
    res.status(503).json({ status: 'degraded' });
  }
});

app.listen(3000, () => console.log('Service running on :3000'));
